async function tableRows(table:string,order='updated_at',_limit=500){const db=await createServiceClient(),rows:Row[]=[];for(let offset=0;;offset+=500){const{data,error}=await db.from(table).select('*').order(order,{ascending:false}).order('id',{ascending:true}).range(offset,offset+499);if(error)throw fail(`charger ${table}`,error);const page=(data||[]) as Row[];rows.push(...page);if(page.length<500)return rows;if(offset>=49500)throw new MarketplaceError('CONFIGURATION_ERROR','Registre trop large: utilisez une sélection paginée explicite.')}}
