function validateCampaign(input:Record<string,unknown>){const kind=text(input.kind) as LiveKind;if(!['popup','broadcast','proof'].includes(kind))throw new MarketplaceError('VALIDATION_ERROR','Type d’expérience invalide.');const purpose=text(input.purpose_key||input.purposeKey);const theme=text(input.theme_key||input.themeKey);if(!LIVE_PURPOSES.some(x=>x.key===purpose&&x.kind===kind))throw new MarketplaceError('VALIDATION_ERROR','Purpose non reconnu.');if(!LIVE_THEMES.some(x=>x.key===theme&&x.kind===kind))throw new MarketplaceError('VALIDATION_ERROR','Thème non reconnu.');const content=obj(input.localized_content||input.localizedContent);if(!text(obj(content.fr).title))throw new MarketplaceError('VALIDATION_ERROR','Le titre français est requis.');return{kind,purpose,theme,content}}
