async function sourceForCampaign(db:DbClient,campaign:LiveCampaign,context:Row={}){const key=text(campaign.truth_source.source_key);if(!key)return null;const{data,error}=await db.from('angelcare_marketplace_live_experience_source_snapshots').select('*').eq('source_key',key).eq('verified',true).eq('status','active').order('observed_at',{ascending:false}).limit(1).maybeSingle();if(error)throw fail('charger la preuve canonique',error);if(!data)return null;const source=mapSource(data as Row);try{const observed=await observeAuthority(source.authority,source.entity_id||'',context);return{...source,payload:observed.payload,observed_at:observed.observed.toISOString(),expires_at:observed.expires.toISOString()}}catch(error){if(error instanceof MarketplaceError&&error.code==='DEPENDENCY_BLOCKED')return null;throw error}}
