export type LiveGovernanceMode='audiences'|'placements'|'schedules'|'experiments'|'history'|'settings'
const GOVERNANCE_TABLE:Record<Exclude<LiveGovernanceMode,'history'>,string>={audiences:'angelcare_marketplace_live_experience_audiences',placements:'angelcare_marketplace_live_experience_placements',schedules:'angelcare_marketplace_live_experience_schedules',experiments:'angelcare_marketplace_live_experience_experiments',settings:'angelcare_marketplace_live_experience_capabilities'}
