export async function transitionLiveGovernance(mode:Exclude<LiveGovernanceMode,'history'>,id:string,next:string,reason:string,context:MarketplaceRequestContext){const db=await createServiceClient(),table=GOVERNANCE_TABLE[mode];const{data:current,error:e}=await db.from(table).select('*').eq('id',id).maybeSingle();if(e||!current)throw new MarketplaceError('NOT_FOUND',`${mode} introuvable.`,{cause:e||undefined});const from=text(current.status)||'draft';if(!GOVERNANCE_TRANSITIONS[mode][from]?.includes(next))throw new MarketplaceError('VALIDATION_ERROR',`Transition ${mode} interdite: ${from} → ${next}.`);if(mode==='schedules'&&['active','scheduled'].includes(next)){const r=obj(current.recurrence),f=text(r.frequency)||'once';if(f!=='once'&&(!text(r.start_time)||!text(r.end_time)||f==='weekly'&&!Array.isArray(r.days)))throw new MarketplaceError('NOT_READY','Complétez les heures et jours du calendrier avant activation.')}const patch:Row={status:next};if('updated_at' in current)patch.updated_at=new Date().toISOString();if(mode==='experiments'&&next==='winner'&&(!text(current.winner_variant)||!arr(current.variants).some(v=>v.key===current.winner_variant)||!text(obj(current.evidence).note)))throw new MarketplaceError('NOT_READY','Le gagnant doit être défini avant la décision winner.');const{data,error}=await db.from(table).update(patch).eq('id',id).select('*').single();if(error||!data)throw fail(`transitionner ${mode}`,error);await audit(db,context,`${mode}.${next}`,id,{from,to:next,reason,label:governanceLabel(mode,data as Row)});return data as Row}

