export async function liveSourceEntities(authority:string,query:string,offset=0){
 const tables:Record<string,string>={catalog_item:'angelcare_marketplace_catalog_items',catalog_availability:'angelcare_marketplace_catalog_items',academy_cohort:'angelcare_marketplace_academy_cohorts',wallet_policy:'angelcare_marketplace_wallet_policies',trust_badge:'angelcare_marketplace_trust_badge_issuances'}
 if(!tables[authority])throw new MarketplaceError('VALIDATION_ERROR','Autorité non supportée.')
 const db=await createServiceClient();let q=db.from(tables[authority]).select('*',{count:'exact'}).order('updated_at',{ascending:false}).range(offset,offset+39)
 if(authority.startsWith('catalog'))q=q.eq('status','published')
 const safeQuery=query.replace(/[^\p{L}\p{N} _-]/gu,'').trim();if(safeQuery){const columns=authority.startsWith('catalog')?['name_fr','item_key']:authority==='academy_cohort'?['name','public_reference']:authority==='wallet_policy'?['name_fr','policy_key']:['badge_key','public_reference'];q=q.or(columns.map(key=>`${key}.ilike.%${safeQuery}%`).join(','))}const result=await q;if(result.error)throw fail('charger les entités de preuve',result.error)
 const rows=(result.data||[]) as Row[];const needle=query.toLocaleLowerCase();return {entities:rows.map(row=>({id:text(row.id),name:text(row.name_fr)||text(row.name)||text(row.badge_key)||text(row.public_reference)||text(row.item_key),reference:text(row.item_key)||text(row.public_reference)||text(row.policy_key)||text(row.badge_key),status:text(row.status)})).filter(row=>!needle||`${row.name} ${row.reference}`.toLocaleLowerCase().includes(needle)),total:result.count||0,offset}
}

async function livePromotion(c:LiveCampaign,bound:NonNullable<Awaited<ReturnType<typeof canonicalOffer>>>,ctx:Row){
 if(!/flash_sale/.test(c.purpose_key)||bound.item.price_mode!=='fixed'||bound.item.price_amount==null)return null
 const native=await resolveAutomaticPromotion({item:bound.item,subtotal:bound.item.price_amount,territoryId:text(ctx.territoryId)||null,customerAccountId:text(ctx.customerAccountId)||null});if(!native||native.id!==text(c.conversion.promotion_id))return null
 const db=await createServiceClient(),{data,error}=await db.from('angelcare_marketplace_promotions').select('ends_at').eq('id',native.id).single();if(error)throw fail('vérifier la promotion native',error);if(!data?.ends_at)return null
 return{...native,original:bound.item.price_amount,effective:Math.max(0,bound.item.price_amount-native.discount),endsAt:c.ends_at&&Date.parse(c.ends_at)<Date.parse(text(data.ends_at))?c.ends_at:text(data.ends_at)}
}
async function validateNativePublication(c:LiveCampaign){
 validatePublish(c)
 const id=text(c.conversion.item_id),bound=id?await canonicalOffer({itemId:id},'fr'):null
 if(id&&!bound)throw new MarketplaceError('DEPENDENCY_BLOCKED','Offre absente du catalogue public canonique.')
 if(!compatiblePurpose(c.purpose_key,bound?.offer.schemaKey||null))throw new MarketplaceError('VALIDATION_ERROR','Schéma atomique incompatible avec cette composition.')
 if(c.kind==='proof'){const source=await sourceForCampaign(await createServiceClient(),c);if(!source||!publicProof(source)||!proofSupports(c.purpose_key,source))throw new MarketplaceError('DEPENDENCY_BLOCKED','Autorité de preuve incompatible, expirée ou absente.');if(bound&&source.authority==='academy_cohort'&&!await cohortBelongsToItem(source,bound.item.id))throw new MarketplaceError('VALIDATION_ERROR','La cohorte appartient à une autre offre.');if(bound&&['catalog_item','catalog_availability'].includes(source.authority)&&source.entity_id!==bound.item.id)throw new MarketplaceError('VALIDATION_ERROR','La preuve appartient à une autre offre.');if(['wallet_topup_bonus_proof'].includes(c.purpose_key))throw new MarketplaceError('DEPENDENCY_BLOCKED','Une politique Wallet générale ne prouve pas un privilège personnel ni un bonus attribué. Utilisez une annonce sans montant ou une autorité d’évaluation dédiée.')}
 if(/flash_sale/.test(c.purpose_key)){if(!bound||!await livePromotion(c,bound,{}))throw new MarketplaceError('DEPENDENCY_BLOCKED','La promotion sélectionnée doit être automatique, active, datée et effectivement applicable à cette offre.');}
}

