async function personalWalletTruth(source:LiveSourceSnapshot,bound:NonNullable<Awaited<ReturnType<typeof canonicalOffer>>>){
 const customer=await getCustomerContext();if(!customer||bound.item.price_mode!=='fixed'||bound.item.price_amount==null||bound.item.currency_label!=='Dh')return null
 const evaluation=await walletComparisonForCustomer({context:customer,normalPrice:bound.item.price_amount,itemId:bound.item.id,categoryKey:bound.item.category_key,schemaKey:bound.offer.schemaKey,territoryId:customer.account.territory_id});if(!evaluation.eligible||!evaluation.evaluationId)return null
 const db=await createServiceClient(),{data,error}=await db.from('angelcare_marketplace_wallet_policy_evaluations').select('id,accepted_policy_ids,customer_account_id,catalog_item_id,status').eq('id',evaluation.evaluationId).single();if(error)throw fail('vérifier l’évaluation Wallet',error);if(!data||data.customer_account_id!==customer.account.id||data.catalog_item_id!==bound.item.id||!Array.isArray(data.accepted_policy_ids)||!data.accepted_policy_ids.includes(source.entity_id)||data.status!=='evaluated')return null
 return{normal_price:evaluation.normalPrice,wallet_price:evaluation.walletPrice,saving:evaluation.immediateSaving,currency:'Dh',benefit_label:evaluation.priorityLabel||'',evaluation_verified:true}
}

async function cohortBelongsToItem(source:LiveSourceSnapshot,itemId:string){const db=await createServiceClient(),result=await db.from('angelcare_marketplace_academy_courses').select('catalog_item_id,status').eq('id',text(source.payload.course_id)).single();if(result.error)throw fail('vérifier la cohorte liée',result.error);return result.data?.status==='published'&&result.data.catalog_item_id===itemId}
